@S(panic_grp, "enable", aliases=["on", "lockdown"])
@owner_only()
async def pm_en(ctx):
    d = sec_cfg(ctx.guild)["panic"]
    g = ctx.guild
    snap = {}
    secured = 0
    for ch in g.text_channels:
        try:
            ow = ch.overwrites_for(g.default_role)
            snap[str(ch.id)] = ow.send_messages
            ow.send_messages = False
            await ch.set_permissions(g.default_role, overwrite=ow, reason=R("Panic Mode Emergency Lockdown"))
            secured += 1
        except Exception:
            pass
    d["active"] = True
    d["on"] = True
    d["secured_channels"] = secured
    d["snapshot"] = snap
    save()
    await send(ctx, "<:security:1570537983856091139> Panic Mode Lockdown Activated", f"{E_ARR} Emergency lockdown is now **Active**. Frozen `{secured}` text channels and saved permission snapshot in vault.", color=BRIGHT_GREEN)

@S(panic_grp, "disable", aliases=["off", "unlock"])
@owner_only()
async def pm_dis(ctx):
    d = sec_cfg(ctx.guild)["panic"]
    g = ctx.guild
    snap = d.get("snapshot") or {}
    restored = 0
    for cid_str, prev_val in snap.items():
        ch = g.get_channel(int(cid_str))
        if ch:
            try:
                ow = ch.overwrites_for(g.default_role)
                ow.send_messages = prev_val
                await ch.set_permissions(g.default_role, overwrite=ow, reason=R("Panic Mode Lockdown Lifted"))
                restored += 1
            except Exception:
                pass
    d["active"] = False
    d["secured_channels"] = 0
    d["snapshot"] = None
    save()
    await send(ctx, "<:security:1570537983856091139> Panic Mode Disabled", f"{E_ARR} Emergency lockdown lifted and restored `{restored}` channels from vault.", color=BRIGHT_GREEN)

