    if state and state.lower() in ("disable", "off"):
        c["roguedemote"] = False
        save()
        return await send(ctx, "<:security:1570537983856091139> Rogue Admin Demotion Protocol", f"{E_CROSS} Deactivated rogue admin containment.", color=BRIGHT_RED)
