@G("logging", aliases=["logs", "logsetup"])
@perm("manage_guild", "Manage Server")
async def logging_grp(ctx):
    await ctx.invoke(log_config_cmd)

@S(logging_grp, "config", aliases=["show", "status"])
@perm("manage_guild", "Manage Server")
async def log_config_cmd(ctx):
    d = log_cfg(ctx.guild)
    g = ctx.guild
    cat_obj = g.get_channel(d.get("cat_id")) if d.get("cat_id") else None
    ch_lines = [
        f"{E_ARR} `{lbl:<16}` → {f'<#{cid}>' if cid else '`Not Set`'}"
        for k, lbl, cname in LOG_STREAMS_16
        for cid in [d["channels"].get(k)]
    ]
    desc = (
        f"**__Logging :__** {'<a:TICK:1571002237243891773>' if d.get('enabled', True) else '<a:rd_wrong_imp:1571002210832220160>'}\n"
        f"**__Category :__** {cat_obj.mention if cat_obj else '#<a:delhi_dot:1570500296147206336> | Server Logs'}\n"
        f"**__Ignore Embeds :__** {'<a:TICK:1571002237243891773>' if d.get('ignore_embeds', True) else '<a:rd_wrong_imp:1571002210832220160>'}\n"
        f"**__Ignore Voice :__** {'<a:TICK:1571002237243891773>' if d.get('ignore_voice', False) else '<a:rd_wrong_imp:1571002210832220160>'}\n\n"
        f"**__Logging Channels :__**\n\n" + "\n".join(ch_lines) +
        f"\n\nRequested by {ctx.author.mention} (`{ctx.author.name}`)"
    )
    await send(ctx, "<a:settings:1570537955477422310> Logging Configuration", desc, thumb=(g.icon.url if g.icon else None))

@S(logging_grp, "wizard", aliases=["setup", "auto"])
@perm("manage_guild", "Manage Server")
async def logging_wiz(ctx):
    msg = await send(ctx, "<a:settings:1570537955477422310> Logging Wizard", f"{E_LOAD} Creating 16 logging channels & dedicated Webhooks...")
    g = ctx.guild
    d = log_cfg(g)
    ow = {
        g.default_role: discord.PermissionOverwrite(view_channel=False),
        g.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_webhooks=True, embed_links=True)
    }
    cat_ch = await g.create_category("<a:delhi_dot:1570500296147206336> | Server Logs", overwrites=ow, reason=R("Logging Wizard"))
    d["cat_id"] = cat_ch.id
    for k, lbl, cname in LOG_STREAMS_16:
        ch = await g.create_text_channel(cname, category=cat_ch, reason=R(f"Logging: {lbl}"))
        d["channels"][k] = ch.id
        try:
            wh = await ch.create_webhook(name=f"{BOT_NAME} — {lbl}", reason=R("Webhook Logging"))
            d["webhooks"][k] = wh.url
        except Exception:
            pass
    save()
    try:
        await msg.delete()
    except Exception:
        pass
    await ctx.invoke(log_config_cmd)

