    desc = f"**__Humans :__** `{humans}`\n**__Bots :__** `{bots}`\n**__Total :__** `{g.member_count}`\n\n<a:TICK:1571002237243891773> **Online :** `{online}`\n<a:delhi_dot:1570500296147206336> **Offline :** `{offline}`"
    await send(ctx, "<a:delhi_dot:1570500296147206336> Member Count", desc, thumb=(g.icon.url if g.icon else None))

