# 14B. MASTER ZERO-TRUST UPGRADE: 35 ANTINUKE EVENTS (LINK ROLE, ONBOARDING SAFE,
#      ROLE POSITION), 5S SILENT COOLDOWN, ANTI-RATELIMIT BLACKLIST, CONCURRENT
#      SAME-ROLE RECOVERY, AUTO-PANIC LOCKDOWN, GUILD CUSTOMIZE & REPLY STEAL
# ==============================================================================
for _new_ev, _new_k, _new_desc, _new_lim in (
    ("Link Role Protection", "linkrole", "Deletes unauthorized linked roles/invites and bans creator", (1, 2)),
    ("Onboarding Safe Guard", "onboard_safe", "Strips join-time dangerous roles & zeroes role permissions", (1, 2)),
    ("Role Position Update", "rlpos", "Blocks unauthorized role hierarchy reordering & restores position", (1, 3)),
):
    if _new_ev not in EVENT_NAMES:
        AN_EVENTS_32.append((_new_ev, _new_k, _new_desc, _new_lim))
        EVENT_NAMES.append(_new_ev)
        EVENT_KEYS[_new_ev] = _new_k
        KEY_TO_EVENT[_new_k] = _new_ev
        EVENT_DESC[_new_ev] = _new_desc
        EVENT_LIMS[_new_ev] = _new_lim

_STRICT_5S_CD = defaultdict(float)
_ABUSE_BUCKETS = defaultdict(lambda: deque(maxlen=25))
_ABUSE_WARNINGS = defaultdict(int)
_BLACKLISTED_USERS = set()

def load_blacklist_db():
    for gid, gdata in DB.items():
        if isinstance(gdata, dict):
            for uid in gdata.get("blacklisted_users", []):
                _BLACKLISTED_USERS.add(int(uid))

load_blacklist_db()

if hasattr(bot, "_checks"):
    bot._checks.clear()

@bot.check
async def strict_5s_cooldown_and_ratelimit_guard(ctx):
    if not ctx.guild or ctx.author.bot:
        return True
    uid = ctx.author.id
    if uid in _BLACKLISTED_USERS and uid != ctx.guild.owner_id:
        return False

    now = time.time()
    ab_dq = _ABUSE_BUCKETS[uid]
    ab_dq.append(now)
    recent_8s = [t for t in ab_dq if now - t <= 8.0]

    if len(recent_8s) >= 6 and uid != ctx.guild.owner_id:
        _ABUSE_WARNINGS[uid] += 1
        if _ABUSE_WARNINGS[uid] == 1:
            try:
                await ctx.reply(
                    embed=fancy(
                        ctx,
                        f"{E_SEC} Anti-Rate-Limit Warning",
                        f"{E_CROSS} {ctx.author.mention}, stop spamming commands to rate-limit **{BOT_NAME}**! One more violation will permanently **Blacklist** you.",
                        color=BRIGHT_RED
                    ),
                    mention_author=False
                )
            except Exception:
                pass
            return False
        else:
            _BLACKLISTED_USERS.add(uid)
            cfg(ctx.guild.id).setdefault("blacklisted_users", []).append(uid)
            save()
            try:
                await ctx.reply(
                    embed=fancy(
                        ctx,
                        f"{E_SEC} User Blacklisted — Rate-Limit Abuse",
                        f"{E_CROSS} {ctx.author.mention} (`{uid}`) has been permanently **Blacklisted** from using **{BOT_NAME}** due to rate-limit abuse.",
                        color=BRIGHT_RED
                    ),
                    mention_author=False
                )
            except Exception:
                pass
            return False

    last_exec = _STRICT_5S_CD[uid]
    if now - last_exec < 5.0 and uid != ctx.guild.owner_id:
        return False
    _STRICT_5S_CD[uid] = now

    c = cfg(ctx.guild.id)
    if uid != ctx.guild.owner_id and uid not in c.get("extraowners", []):
        cmd_root = ctx.command.root_parent.name if ctx.command and ctx.command.root_parent else (ctx.command.name if ctx.command else "")
        lock_map = {
            "automod": "automod", "blword": "automod",
            "logging": "logging", "greet": "welcome",
            "autorole": "autorole", "ticket": "ticket",
            "giveaway": "giveaway", "reactionrole": "reactionrole",
            "autoresponder": "autoresponder", "autoreact": "autoreact",
            "customrole": "customrole", "sticky": "sticky",
            "joindm": "joindm", "vcrole": "j2c",
        }
        mod_key = lock_map.get(cmd_root)
        if mod_key:
            is_locked = c.get("setuplock", False) or c.get("setuplock_modules", {}).get(mod_key, False)
            if is_locked and uid not in c.get("setuplock_bypass", []):
                record_setuplock_block(ctx.guild.id, uid, str(ctx.author), mod_key, ctx.command.qualified_name)
                await send(ctx, f"{E_SEC} Setup Lock Active", f"{E_CROSS} Module `{mod_key}` is locked by **Setup Lock**.", color=BRIGHT_RED)
                raise Denied()
    return True

_MASS_DESTRUCTION_TRACKER = defaultdict(lambda: deque(maxlen=30))

async def trigger_auto_panic_lockdown(g: discord.Guild, trigger_reason: str, hide_channel: discord.TextChannel = None):
    d = sec_cfg(g)["panic"]
    if hide_channel:
        try:
            ow = hide_channel.overwrites_for(g.default_role)
            ow.view_channel = False
            ow.send_messages = False
            await hide_channel.set_permissions(g.default_role, overwrite=ow, reason=R(f"Auto-Hide: {trigger_reason}"))
        except Exception:
            pass
    if d.get("active"):
        return
    snap = {}
    tasks_lock = []
    for ch in g.text_channels:
        ow = ch.overwrites_for(g.default_role)
        snap[str(ch.id)] = ow.send_messages
        ow.send_messages = False
        tasks_lock.append(ch.set_permissions(g.default_role, overwrite=ow, reason=R(f"Auto-Panic Lockdown: {trigger_reason}")))
    results = await asyncio.gather(*tasks_lock, return_exceptions=True)
    secured = sum(1 for r in results if not isinstance(r, Exception))
    d["active"] = True
    d["on"] = True
    d["secured_channels"] = secured
    d["snapshot"] = snap
    save()
    await send_webhook_log(
        g, "alert", f"{E_SEC} AUTO-PANIC MODE LOCKDOWN ACTIVATED",
        f"{E_ARR} **Trigger:** `{trigger_reason}`\n"
        f"{E_ARR} **Hidden Channel:** {hide_channel.mention if hide_channel else '`All Public Channels Frozen`'}\n"
        f"{E_ARR} **Secured Channels:** `{secured}`",
        BRIGHT_RED
    )

async def execute_zero_trust_punishment(g: discord.Guild, executor: discord.abc.User, event_name: str, target_name: str, reason_detail: str, recovery_coro=None):
    if not g or not executor or (bot.user and executor.id == bot.user.id) or executor.id == g.owner_id:
        return
    c = cfg(g.id)
    if not c.get("enabled", True):
        return
    if not c.get("an_filters", {}).get(event_name, True):
        return

    now = time.time()
    md_dq = _MASS_DESTRUCTION_TRACKER[g.id]
    md_dq.append(now)
    if sum(1 for t in md_dq if now - t <= 10.0) >= 5:
        asyncio.create_task(trigger_auto_panic_lockdown(g, f"Mass Server Destruction Detected ({event_name})"))

    dedup_key = (g.id, executor.id)
    punish_mode = c.get("punishment", "ban").lower()

    async def _run_containment():
        async with _PUNISHMENT_LOCKS[dedup_key]:
            if now - _PUNISHED_RECENT.get(dedup_key, 0) <= 3.0:
                return f"Already Contained ({punish_mode.upper()})"
            _PUNISHED_RECENT[dedup_key] = now
            c.get("whitelist", {}).pop(str(executor.id), None)
            member = g.get_member(executor.id)

            dm_embed = discord.Embed(
                title=f"{E_SEC} Zero-Trust Anti-Nuke Ban Notice",
                description=(
                    f"{E_ARR} **Server:** `{g.name}` (`{g.id}`)\n"
                    f"{E_ARR} **Anti-Nuke Event:** `{event_name}`\n"
                    f"{E_ARR} **Target Resource:** `{target_name}`\n"
                    f"{E_ARR} **Reason:** `{reason_detail}`\n"
                    f"{E_ARR} **Action Taken:** `{punish_mode.upper()}`"
                ),
                color=BRIGHT_RED
            )
            try:
                if not getattr(executor, "bot", False):
                    await executor.send(embed=dm_embed)
            except Exception:
                pass

            if member:
                safe_roles = [r for r in member.roles if r != g.default_role and not dangerous(r) and not r.managed]
                try:
                    await member.edit(roles=safe_roles, reason=R(f"Zero-Trust Strip Roles: {event_name}"))
                except Exception:
                    pass

            try:
                if punish_mode == "ban" or getattr(executor, "bot", False):
                    await g.ban(executor, reason=R(f"{event_name} | {reason_detail}"), delete_message_days=0)
                    return "BANNED + DM SENT (Sub-10ms)"
                elif punish_mode == "kick" and member:
                    await member.kick(reason=R(f"{event_name} | {reason_detail}"))
                    return "KICKED + DM SENT"
                elif punish_mode == "quarantine" and member:
                    qrole = await ensure_quarantine_role(g)
                    keep = [r for r in member.roles if r.managed]
                    await member.edit(roles=keep + [qrole], reason=R(f"Quarantined: {event_name}"))
                    return "QUARANTINED + DM SENT"
                return "DANGEROUS ROLES STRIPPED + DM SENT"
            except Exception as exc:
                return f"Hierarchy Equal/Above ({type(exc).__name__}) — Action 100% Reverted"

    async def _run_recovery():
        if recovery_coro is None:
            return "Not Required"
        if not c.get("autorecovery", True):
            return "Auto-Recovery Disabled"
        try:
            res = await recovery_coro()
            return res or "100% Superfast Recovered"
        except Exception as exc:
            return f"Recovery Attempted ({type(exc).__name__})"

    punish_status, recovery_status = await asyncio.gather(_run_containment(), _run_recovery())
    record_security_incident(g.id, executor.id, str(executor), event_name, target_name, reason_detail, punish_status, recovery_status)

    log_desc = (
        f"{E_SEC} **__Zero-Trust Anti-Nuke Intervention__**\n\n"
        f"{E_ARR} **Protected Event:** `{event_name}` (`{EVENT_KEYS.get(event_name, 'sec')}`)\n"
        f"{E_ARR} **Executor:** {executor.mention} (`{executor}` | `{executor.id}`)\n"
        f"{E_ARR} **Target Resource:** `{target_name}`\n"
        f"{E_ARR} **Detection Reason:** `{reason_detail}`\n"
        f"{E_ARR} **Punishment Applied:** `{punish_status}`\n"
        f"{E_ARR} **Auto-Recovery Status:** `{recovery_status}`\n"
        f"{E_ARR} **Timestamp:** <t:{int(now)}:F> (<t:{int(now)}:R>)"
    )
