@bot.event
async def on_guild_role_create(role: discord.Role):
    g = role.guild
    is_linked_role = bool(getattr(role.tags, "guild_connections", False) or getattr(role.tags, "integration_id", None))
    if is_linked_role:
        entry = await fetch_verified_audit_entry(g, discord.AuditLogAction.role_create, role.id)
        actor = entry.user if entry else None
        if actor and not is_trusted(g, actor.id, "Link Role Protection"):
            async def _rec_lr():
                try:
                    await role.delete(reason=R("Link Role Protection: Deleted Linked Role"))
                except Exception:
                    pass
                try:
                    for inv in await g.invites():
                        if inv.inviter and inv.inviter.id == actor.id:
                            await inv.delete(reason=R("Link Role Protection: Purged Invite"))
                except Exception:
                    pass
                return f"Deleted Linked Role @{role.name} & Purged Invites"
            await execute_zero_trust_punishment(g, actor, "Link Role Protection", f"@{role.name}", "Unauthorized Linked Role Created", _rec_lr)
            return

    if role.managed:
        return
    snapshot_role(role)
    entry = await fetch_verified_audit_entry(g, discord.AuditLogAction.role_create, role.id)
    if not entry or not entry.user:
        return
    should_punish, reason = check_sliding_velocity(g, entry.user.id, "Role Create", "role_creates_min")
    if not should_punish:
        return

    async def _recover_created_role():
        await role.delete(reason=R("Auto-Recovery: Deleted Unauthorized Role"))
        return f"Deleted Unauthorized Role @{role.name}"

    await execute_zero_trust_punishment(g, entry.user, "Role Create", f"@{role.name} ({role.id})", reason, _recover_created_role)

@bot.event
async def on_guild_role_update(before: discord.Role, after: discord.Role):
    g = after.guild
    c = cfg(g.id)
    s = sec_cfg(g)

    if s["wallrole"].get("on") and after.id == s["wallrole"].get("role"):
        if after.permissions.value != 0:
            try:
                await after.edit(permissions=discord.Permissions.none(), reason=R("Wall Role Tamper Protection: Permissions Reset to 0"))
            except Exception:
                pass

    if after.id in c.get("mainroles", []):
        if dangerous(after) or after.mentionable:
            clean = discord.Permissions(after.permissions.value)
            clean.update(administrator=False, ban_members=False, kick_members=False, manage_guild=False, manage_roles=False, manage_channels=False, manage_webhooks=False, mention_everyone=False)
            try:
                await after.edit(permissions=clean, mentionable=False, reason=R("Mainrole Shield Auto-Revert"))
            except Exception:
                pass

    # Check Role Position Update
    if before.position != after.position:
        entry_pos = await fetch_verified_audit_entry(g, discord.AuditLogAction.role_update, after.id)
        if entry_pos and entry_pos.user and not is_trusted(g, entry_pos.user.id, "Role Position Update"):
            should_p_pos, reason_pos = check_sliding_velocity(g, entry_pos.user.id, "Role Position Update", "role_updates_min")
            if should_p_pos:
                async def _rec_pos():
                    await after.edit(position=before.position, reason=R("Auto-Recovery: Reverted Role Position Update"))
                    snapshot_role(after)
                    return f"Restored @{after.name} Hierarchy Position #{before.position}"
                await execute_zero_trust_punishment(g, entry_pos.user, "Role Position Update", f"@{after.name} (#{after.position} -> #{before.position})", reason_pos, _rec_pos)
                return

    if before.name == after.name and before.permissions == after.permissions and before.colour == after.colour and before.hoist == after.hoist:
        return

    entry = await fetch_verified_audit_entry(g, discord.AuditLogAction.role_update, after.id)
    if not entry or not entry.user:
        snapshot_role(after)
        return
    should_punish, reason = check_sliding_velocity(g, entry.user.id, "Role Update", "role_updates_min")
    if not should_punish:
        snapshot_role(after)
        return

    async def _recover_role_update():
        await after.edit(
            name=before.name,
            permissions=before.permissions,
            colour=before.colour,
            hoist=before.hoist,
            mentionable=before.mentionable,
            reason=R("Auto-Recovery: Reverted Unauthorized Role Update")
        )
        snapshot_role(after)
        return f"Reverted Role @{before.name} Permissions & Settings"

    await execute_zero_trust_punishment(g, entry.user, "Role Update", f"@{after.name} ({after.id})", reason, _recover_role_update)

async def onboarding_safe_guard_check(member: discord.Member):
    g = member.guild
    if not g or member.id == g.owner_id or (bot.user and member.id == bot.user.id):
        return
    if member.joined_at and (datetime.now(timezone.utc) - member.joined_at).total_seconds() <= 30.0:
        dang_roles = [r for r in member.roles if r != g.default_role and dangerous(r)]
        if dang_roles and not is_trusted(g, member.id, "Onboarding Safe Guard"):
            coros = []
            safe_member_roles = [r for r in member.roles if r not in dang_roles]
            coros.append(member.edit(roles=safe_member_roles, reason=R("Onboarding Safe Guard: Stripped Join-Time Dangerous Role")))
            for dr in dang_roles:
                clean_p = discord.Permissions(dr.permissions.value)
                clean_p.update(
                    administrator=False, ban_members=False, kick_members=False,
                    manage_guild=False, manage_roles=False, manage_channels=False,
                    manage_webhooks=False, mention_everyone=False, manage_emojis_and_stickers=False
                )
                coros.append(dr.edit(permissions=clean_p, reason=R("Onboarding Safe Guard: Zeroed Dangerous Role Permissions")))
            await asyncio.gather(*coros, return_exceptions=True)
            await send_webhook_log(
                g, "alert", f"{E_SEC} Onboarding Safe Guard Triggered",
                f"{E_ARR} **Member:** {member.mention} (`{member.id}`)\n"
                f"{E_ARR} **Stripped Roles:** {', '.join(r.mention for r in dang_roles)}\n"
                f"{E_ARR} **Action:** `Roles Stripped & Dangerous Permissions Turned OFF Sub-Second`",
                BRIGHT_RED
            )

async def edit_guild_bot_profile(guild: discord.Guild, *, avatar_bytes: bytes = None, banner_bytes: bytes = None, bio: str = None, nick: str = None, reset_all: bool = False):
    payload = {}
    if reset_all:
        payload = {"avatar": None, "banner": None, "bio": "", "nick": None}
    else:
        if avatar_bytes is not None:
            b64_av = base64.b64encode(avatar_bytes).decode("ascii")
            payload["avatar"] = f"data:image/png;base64,{b64_av}"
        if banner_bytes is not None:
            b64_bn = base64.b64encode(banner_bytes).decode("ascii")
            payload["banner"] = f"data:image/png;base64,{b64_bn}"
        if bio is not None:
            payload["bio"] = bio
        if nick is not None:
            payload["nick"] = nick
    route = discord.http.Route("PATCH", "/guilds/{guild_id}/members/@me", guild_id=guild.id)
    await bot.http.request(route, json=payload)

