@C("steal", aliases=["addemoji", "cloneemoji"])
@perm("manage_emojis", "Manage Emojis / Stickers")
async def steal_reply_cmd(ctx, emoji_input: str = None, *, custom_name: str = None):
    target_content = emoji_input or ""
    target_attachments = list(ctx.message.attachments)
    target_stickers = list(ctx.message.stickers)

    if ctx.message.reference and ctx.message.reference.message_id:
        try:
            ref_msg = ctx.message.reference.resolved or await ctx.channel.fetch_message(ctx.message.reference.message_id)
            if ref_msg:
                if not target_content:
                    target_content = ref_msg.content or ""
                if not target_attachments:
                    target_attachments = list(ref_msg.attachments)
                if not target_stickers:
                    target_stickers = list(ref_msg.stickers)
        except Exception:
            pass

    m_em = re.search(r"<(a?):([a-zA-Z0-9_]+):(\d+)>", target_content)
    if m_em:
        is_anim = bool(m_em.group(1))
        em_name = (custom_name or m_em.group(2)).strip().replace(" ", "_")[:32]
        em_id = m_em.group(3)
        ext = "gif" if is_anim else "png"
        url = f"https://cdn.discordapp.com/emojis/{em_id}.{ext}?quality=lossless"
        async with aiohttp.ClientSession() as sess:
            async with sess.get(url) as resp:
                if resp.status == 200:
                    data = await resp.read()
                    created_em = await ctx.guild.create_custom_emoji(name=em_name, image=data, reason=R(f"Stolen by {ctx.author}"))
                    return await send(ctx, f"{E_TICK} Emoji Stolen Successfully", f"{E_ARR} Added {created_em} as `:{created_em.name}:` to **{ctx.guild.name}**!", color=BRIGHT_GREEN)

    if target_stickers:
        st = target_stickers[0]
        async with aiohttp.ClientSession() as sess:
            async with sess.get(st.url) as resp:
                if resp.status == 200:
                    data = await resp.read()
                    nm = re.sub(r"\W+", "_", custom_name or st.name)[:30] or "stolen_emoji"
                    created_em = await ctx.guild.create_custom_emoji(name=nm, image=data, reason=R(f"Stolen sticker by {ctx.author}"))
                    return await send(ctx, f"{E_TICK} Sticker Stolen as Emoji", f"{E_ARR} Added {created_em} (`:{created_em.name}:`) to **{ctx.guild.name}**!", color=BRIGHT_GREEN)

    if target_attachments:
        att = target_attachments[0]
        data = await att.read()
        nm = re.sub(r"\W+", "_", custom_name or att.filename.split(".")[0])[:30] or "stolen_emoji"
        created_em = await ctx.guild.create_custom_emoji(name=nm, image=data, reason=R(f"Stolen attachment by {ctx.author}"))
        return await send(ctx, f"{E_TICK} Image Stolen as Emoji", f"{E_ARR} Added {created_em} (`:{created_em.name}:`) to **{ctx.guild.name}**!", color=BRIGHT_GREEN)

    await send(ctx, "", f"{E_CROSS} Reply to a message containing an emoji/sticker/image or provide `<emoji>` to steal!", color=BRIGHT_RED)

