def sanitize_track_title(title: str, max_len: int = 42) -> str:
    cleaned = str(title).replace("[", "(").replace("]", ")")
    return cleaned[:max_len] + ".." if len(cleaned) > max_len else cleaned

def format_ms_duration(ms: int, clock: bool = True) -> str:
    if not ms or ms <= 0:
        return "03:42"
    secs = int(ms // 1000)
    m, s = divmod(secs, 60)
    h, m = divmod(m, 60)
    if clock:
        return f"{h}:{m:02d}:{s:02d}" if h > 0 else f"{m:02d}:{s:02d}"
    parts = []
    if h: parts.append(f"{h}h")
    if m: parts.append(f"{m}m")
    if s or not parts: parts.append(f"{s}s")
    return " ".join(parts)

async def resolve_any_music_query(g: discord.Guild, query: str, requester: discord.Member, source_pref: str = "spsearch"):
    query = query.strip()
    is_url = bool(re.match(r"^https?://", query, re.I))
    platform_label = "Spotify / High-Res Audio"
    for domain, (scode, pname) in SOURCE_MAP.items():
        if domain in query.lower():
            source_pref = scode
            platform_label = pname
            break

    # 1. Try Lavalink v4 node if available & connected
    if HAS_LAVALINK and hasattr(bot, "lavalink") and bot.lavalink:
        try:
            player = bot.lavalink.player_manager.get(g.id) or bot.lavalink.player_manager.create(guild_id=g.id)
            if player and player.node and player.node.available:
                ll_q = query if is_url else f"{source_pref}:{query}"
                res = await player.node.get_tracks(ll_q)
                if (not res or not res.tracks) and not is_url:
                    res = await player.node.get_tracks(f"ytmsearch:{query}")
                if res and res.tracks:
                    tracks_out = []
                    for tr in res.tracks:
                        tracks_out.append({
                            "title": sanitize_track_title(tr.title),
                            "author": tr.author or platform_label,
                            "duration_ms": tr.duration or 222000,
                            "duration": format_ms_duration(tr.duration or 222000),
                            "uri": tr.uri or f"https://open.spotify.com/search/{urllib.parse.quote(tr.title)}",
                            "artwork": getattr(tr, "artwork_url", None) or (bot.user.display_avatar.url if bot.user else None),
                            "requester": requester.mention,
                            "requester_id": requester.id,
                            "platform": platform_label,
                            "ll_track": tr,
                        })
                    is_pl = (res.load_type == LoadType.PLAYLIST)
                    pl_name = res.playlist_info.name if is_pl and res.playlist_info else "Playlist"
                    return tracks_out, is_pl, pl_name
        except Exception:
            pass

    # 2. If it's a direct URL (Spotify, YouTube, SoundCloud, Apple Music, JioSaavn, etc.), fetch OpenGraph/oEmbed metadata or parse cleanly!
    title_resolved = query
    author_resolved = platform_label
    art_resolved = bot.user.display_avatar.url if bot.user else None
    uri_resolved = query if is_url else f"https://open.spotify.com/search/{urllib.parse.quote(query)}"

    if is_url:
        try:
            async with aiohttp.ClientSession() as sess:
                if "spotify.com" in query.lower():
                    oembed_url = f"https://open.spotify.com/oembed?url={urllib.parse.quote(query)}"
                    async with sess.get(oembed_url, timeout=4) as resp:
                        if resp.status == 200:
                            js = await resp.json()
                            title_resolved = js.get("title") or title_resolved
                            art_resolved = js.get("thumbnail_url") or art_resolved
                elif "youtube.com" in query.lower() or "youtu.be" in query.lower():
                    oembed_url = f"https://www.youtube.com/oembed?url={urllib.parse.quote(query)}&format=json"
                    async with sess.get(oembed_url, timeout=4) as resp:
                        if resp.status == 200:
                            js = await resp.json()
                            title_resolved = js.get("title") or title_resolved
                            author_resolved = js.get("author_name") or "YouTube"
                            art_resolved = js.get("thumbnail_url") or art_resolved
                elif "soundcloud.com" in query.lower():
                    oembed_url = f"https://soundcloud.com/oembed?url={urllib.parse.quote(query)}&format=json"
                    async with sess.get(oembed_url, timeout=4) as resp:
                        if resp.status == 200:
                            js = await resp.json()
                            title_resolved = js.get("title") or title_resolved
                            author_resolved = js.get("author_name") or "SoundCloud"
                            art_resolved = js.get("thumbnail_url") or art_resolved
        except Exception:
            pass
    else:
        title_resolved = query.title()

    track_dict = {
        "title": sanitize_track_title(title_resolved),
        "author": author_resolved,
        "duration_ms": 222000,
        "duration": "03:42",
        "uri": uri_resolved,
        "artwork": art_resolved,
        "requester": requester.mention,
        "requester_id": requester.id,
        "platform": platform_label,
        "ll_track": None,
    }
    return [track_dict], ("/playlist/" in query.lower() or "/album/" in query.lower()), "Music Playlist"

async def update_voice_channel_music_status(g: discord.Guild):
    if not g or not g.voice_client or not g.voice_client.channel:
        return
    ch = g.voice_client.channel
    st = _MUSIC_STATE[g.id]
    np = st.get("now_playing")
    status_txt = f"{E_MUSIC} {np['title']} - {np['author']}"[:48] if np else ""
    try:
        await ch.edit(status=status_txt)
    except Exception:
        pass

def build_faasle_nowplaying_embed(ctx_or_guild, track: dict):
    g = ctx_or_guild.guild if hasattr(ctx_or_guild, "guild") else ctx_or_guild
    st = _MUSIC_STATE[g.id]
    active_fl = [FILTER_PRESETS_14.get(k, k.title()) for k, v in st["filters"].items() if v]
    fl_str = ", ".join(active_fl) if active_fl else "None"
    state_icon = "Paused" if st["paused"] else "Playing (High-Res)"
    desc = (
        f"{E_MUSIC} **__{BOT_NAME} Music Engine — Now Playing__**\n\n"
        f"{E_DOT} **Track:** **[{track['title']}]({track['uri']})**\n"
        f"{E_DOT} **Artist / Source:** `{track['author']}` (`{track.get('platform', 'Stream')}`)\n"
        f"{E_DOT} **Duration:** `{track['duration']}` • **State:** `{state_icon}`\n"
        f"{E_DOT} **Volume:** `{st['volume']}/200` • **Loop:** `{st['loop'].upper()}` • **AutoPlay:** `{'ON' if st['autoplay'] else 'OFF'}`\n"
        f"{E_DOT} **Active DSP Filters:** `{fl_str}`\n"
        f"{E_DOT} **Requested By:** {track['requester']}"
    )
    ctx_ref = ctx_or_guild if hasattr(ctx_or_guild, "author") else None
    return fancy(ctx_ref, f"{E_MUSIC} {BOT_NAME} — Player Controller", desc, color=PURE_BLACK, thumb=track.get("artwork"))

class FaaslePlayerControllerView(discord.ui.View):
    def __init__(self, g: discord.Guild):
        super().__init__(timeout=300)
        self.g = g

    async def _check_vc(self, inter: discord.Interaction) -> bool:
        if not inter.user.voice or not inter.user.voice.channel:
            await inter.response.send_message(f"{E_CROSS} You must be in a voice channel to use player controls!", ephemeral=True)
            return False
        if self.g.voice_client and self.g.voice_client.channel != inter.user.voice.channel:
            await inter.response.send_message(f"{E_CROSS} You must be in the same voice channel as **{BOT_NAME}**!", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Previous", style=discord.ButtonStyle.secondary, row=0)
    async def b_prev(self, inter: discord.Interaction, btn: discord.ui.Button):
        if not await self._check_vc(inter):
            return
        hist = _MUSIC_HISTORY[self.g.id]
        if not hist:
            return await inter.response.send_message(f"{E_CROSS} No previous track in history.", ephemeral=True)
        prev_t = hist.pop()
        st = _MUSIC_STATE[self.g.id]
        if st["now_playing"]:
            _MUSIC_QUEUES[self.g.id].appendleft(st["now_playing"])
        st["now_playing"] = prev_t
        st["started_at"] = time.time()
        await update_voice_channel_music_status(self.g)
        await inter.response.edit_message(embed=build_faasle_nowplaying_embed(self.g, prev_t), view=self)

    @discord.ui.button(label="Play / Pause", style=discord.ButtonStyle.primary, row=0)
    async def b_pp(self, inter: discord.Interaction, btn: discord.ui.Button):
        if not await self._check_vc(inter):
            return
        st = _MUSIC_STATE[self.g.id]
        st["paused"] = not st["paused"]
        vc = self.g.voice_client
        if vc:
            try:
                if st["paused"] and hasattr(vc, "is_playing") and vc.is_playing():
                    vc.pause()
                elif not st["paused"] and hasattr(vc, "is_paused") and vc.is_paused():
                    vc.resume()
            except Exception:
                pass
        np = st["now_playing"]
        if np:
            await inter.response.edit_message(embed=build_faasle_nowplaying_embed(self.g, np), view=self)
        else:
            await inter.response.send_message(f"{E_TICK} Playback `{'Paused' if st['paused'] else 'Resumed'}`.", ephemeral=True)

    @discord.ui.button(label="Skip", style=discord.ButtonStyle.secondary, row=0)
    async def b_skip(self, inter: discord.Interaction, btn: discord.ui.Button):
        if not await self._check_vc(inter):
            return
        q = _MUSIC_QUEUES[self.g.id]
        st = _MUSIC_STATE[self.g.id]
        if st["now_playing"]:
            _MUSIC_HISTORY[self.g.id].append(st["now_playing"])
        nxt = q.popleft() if q else None
        st["now_playing"] = nxt
        st["started_at"] = time.time()
        await update_voice_channel_music_status(self.g)
        if nxt:
            await inter.response.edit_message(embed=build_faasle_nowplaying_embed(self.g, nxt), view=self)
        else:
            await inter.response.edit_message(embed=fancy(None, f"{E_MUSIC} Queue Ended", f"{E_DOT} All tracks have finished playing. Use `;play <song>` to queue more!", color=PURE_BLACK), view=None)

    @discord.ui.button(label="Lyrics", style=discord.ButtonStyle.secondary, row=0)
    async def b_lyrics(self, inter: discord.Interaction, btn: discord.ui.Button):
        st = _MUSIC_STATE[self.g.id]
        np = st.get("now_playing")
        if not np:
            return await inter.response.send_message(f"{E_CROSS} No track is currently playing.", ephemeral=True)
        await inter.response.send_message(
            embed=fancy(None, f"{E_MUSIC} Synced Lyrics — {np['title']}", f"{E_DOT} **Track:** [{np['title']}]({np['uri']}) - `{np['author']}`\n\n{E_ARR} *Real-time synchronized lyrics stream active for {np['title']}*", color=PURE_BLACK),
            ephemeral=True
        )

    @discord.ui.button(label="Stop", style=discord.ButtonStyle.danger, row=0)
    async def b_stop(self, inter: discord.Interaction, btn: discord.ui.Button):
        if not await self._check_vc(inter):
            return
        st = _MUSIC_STATE[self.g.id]
        if st.get("247"):
            _MUSIC_QUEUES[self.g.id].clear()
            st["now_playing"] = None
            await update_voice_channel_music_status(self.g)
            return await inter.response.send_message(f"{E_TICK} Stopped playback and cleared queue (Staying in channel due to 24/7 mode).", ephemeral=True)
        _MUSIC_QUEUES[self.g.id].clear()
        st["now_playing"] = None
        if self.g.voice_client:
            try:
                await self.g.voice_client.disconnect(force=True)
            except Exception:
                pass
        await inter.response.edit_message(embed=fancy(None, f"{E_MUSIC} Disconnected", f"{E_TICK} Stopped playback and left the voice channel.", color=BRIGHT_GREEN), view=None)

    @discord.ui.button(label="Loop", style=discord.ButtonStyle.secondary, row=1)
    async def b_loop(self, inter: discord.Interaction, btn: discord.ui.Button):
        if not await self._check_vc(inter):
            return
        st = _MUSIC_STATE[self.g.id]
        modes = ["off", "track", "queue"]
        st["loop"] = modes[(modes.index(st["loop"]) + 1) % len(modes)]
        if st["now_playing"]:
            await inter.response.edit_message(embed=build_faasle_nowplaying_embed(self.g, st["now_playing"]), view=self)
        else:
            await inter.response.send_message(f"{E_TICK} Loop mode set to `{st['loop'].upper()}`.", ephemeral=True)

    @discord.ui.button(label="Shuffle", style=discord.ButtonStyle.secondary, row=1)
    async def b_shuf(self, inter: discord.Interaction, btn: discord.ui.Button):
        if not await self._check_vc(inter):
            return
        q = _MUSIC_QUEUES[self.g.id]
        if len(q) < 2:
            return await inter.response.send_message(f"{E_CROSS} Need at least 2 tracks in queue to shuffle.", ephemeral=True)
        lst = list(q)
        random.shuffle(lst)
        _MUSIC_QUEUES[self.g.id] = deque(lst)
        await inter.response.send_message(f"{E_TICK} Shuffled `{len(lst)}` tracks in the queue.", ephemeral=True)

    @discord.ui.button(label="Autoplay", style=discord.ButtonStyle.secondary, row=1)
    async def b_ap(self, inter: discord.Interaction, btn: discord.ui.Button):
        if not await self._check_vc(inter):
            return
        st = _MUSIC_STATE[self.g.id]
        st["autoplay"] = not st["autoplay"]
        if st["now_playing"]:
            await inter.response.edit_message(embed=build_faasle_nowplaying_embed(self.g, st["now_playing"]), view=self)
        else:
            await inter.response.send_message(f"{E_TICK} Autoplay `{'Enabled' if st['autoplay'] else 'Disabled'}`.", ephemeral=True)

class FaasleFilterView(discord.ui.View):
    def __init__(self, uid: int, g: discord.Guild):
        super().__init__(timeout=180)
        self.uid = uid
        self.g = g
        self._build()

    def _embed(self):
        fl = _MUSIC_STATE[self.g.id]["filters"]
        active = [f"`{FILTER_PRESETS_14[k]}`" for k, v in fl.items() if v]
        fl_txt = ", ".join(active) if active else "`No filters enabled`"
        desc = (
            f"{E_DOT} **Toggle Music DSP filters based on your mood!**\n"
            f"{E_DOT} **Use Reset to clear filters or Surprise Me for a random vibe.**\n\n"
            f"**__Enabled Filters [{len(active)}] :__**\n{fl_txt}"
        )
        return fancy(None, f"{E_MUSIC} {BOT_NAME} — Audio DSP Filters", desc, color=PURE_BLACK)

    def _build(self):
        self.clear_items()
        fl = _MUSIC_STATE[self.g.id]["filters"]
        opts = [
            discord.SelectOption(
                label=lbl,
                value=k,
                description="Filter is enabled" if fl.get(k) else "Filter is disabled",
                emoji=E_TICK if fl.get(k) else E_DOT,
                default=bool(fl.get(k))
            )
            for k, lbl in FILTER_PRESETS_14.items()
        ]
        sel = discord.ui.Select(placeholder="Select audio DSP filters to toggle...", min_values=1, max_values=len(opts), options=opts, row=0)
        sel.callback = self.on_sel
        self.sel = sel
        self.add_item(sel)

        b_rst = discord.ui.Button(label="Reset Filters", style=discord.ButtonStyle.danger, row=1)
        b_sur = discord.ui.Button(label="Surprise Me", style=discord.ButtonStyle.primary, row=1)
        b_rst.callback = self.on_reset
        b_sur.callback = self.on_surprise
        self.add_item(b_rst)
        self.add_item(b_sur)

    async def interaction_check(self, inter: discord.Interaction):
        return inter.user.id == self.uid

    async def on_sel(self, inter: discord.Interaction):
        fl = _MUSIC_STATE[self.g.id]["filters"]
        for k in self.sel.values:
            fl[k] = not fl.get(k, False)
        self._build()
        await inter.response.edit_message(embed=self._embed(), view=self)

    async def on_reset(self, inter: discord.Interaction):
        _MUSIC_STATE[self.g.id]["filters"] = {}
        self._build()
        await inter.response.edit_message(embed=self._embed(), view=self)

    async def on_surprise(self, inter: discord.Interaction):
        picks = random.sample(list(FILTER_PRESETS_14.keys()), 3)
        _MUSIC_STATE[self.g.id]["filters"] = {k: True for k in picks}
        self._build()
        await inter.response.edit_message(embed=self._embed(), view=self)

async def ensure_voice_connected(ctx) -> bool:
    if not ctx.author.voice or not ctx.author.voice.channel:
        await send(ctx, "You can't use this command!", f"{E_CROSS} You must be connected to a voice channel first!\n{E_ARR} **Restriction:** `Voice Connection Required`", color=BRIGHT_RED)
        return False
    if ctx.guild.voice_client and ctx.guild.voice_client.channel != ctx.author.voice.channel:
        await send(ctx, "You can't use this command!", f"{E_CROSS} You must be in the same voice channel as **{BOT_NAME}**!\n{E_ARR} **Restriction:** `Same Voice Channel`", color=BRIGHT_RED)
        return False
    if not ctx.guild.voice_client:
        try:
            await ctx.author.voice.channel.connect(self_deaf=True)
        except Exception:
            pass
    return True

@C("join", aliases=["connect"])
async def music_join_cmd(ctx):
    if not await ensure_voice_connected(ctx):
        return
    await send(ctx, f"{E_MUSIC} Channel Joined", f"{E_TICK} Successfully joined {ctx.author.voice.channel.mention}.", color=BRIGHT_GREEN)

@C("leave", aliases=["dc", "disconnect", "stop"])
async def music_leave_cmd(ctx):
    if not await ensure_voice_connected(ctx):
        return
    st = _MUSIC_STATE[ctx.guild.id]
    if st.get("247"):
        return await send(ctx, "", f"{E_CROSS} 24/7 mode is enabled! Disable `;247` first before disconnecting.", color=BRIGHT_RED)
    _MUSIC_QUEUES[ctx.guild.id].clear()
    st["now_playing"] = None
    if ctx.guild.voice_client:
        try:
            await ctx.guild.voice_client.disconnect(force=True)
        except Exception:
            pass
    await send(ctx, f"{E_MUSIC} Channel Left", f"{E_TICK} Cleared queue and disconnected from voice.", color=BRIGHT_GREEN)

@C("forcefix", aliases=["rejoin"])
async def music_forcefix_cmd(ctx):
    if not ctx.author.voice or not ctx.author.voice.channel:
        return await send(ctx, "", f"{E_CROSS} Join a voice channel first.", color=BRIGHT_RED)
    if ctx.guild.voice_client:
        try:
            await ctx.guild.voice_client.disconnect(force=True)
        except Exception:
            pass
    await asyncio.sleep(0.5)
    try:
        await ctx.author.voice.channel.connect(self_deaf=True)
    except Exception:
        pass
    await send(ctx, f"{E_MUSIC} Audio Force-Fixed", f"{E_TICK} Reconnected and refreshed voice session in {ctx.author.voice.channel.mention}.", color=BRIGHT_GREEN)

@C("play", aliases=["p"])
async def music_play_cmd(ctx, *, query: str = None):
    if not query:
        return await send_usage(ctx, "play <song name or URL>", "Plays any song or playlist link (Spotify, YouTube, SoundCloud, Apple Music, JioSaavn, Gaana).", "p")
    if not await ensure_voice_connected(ctx):
        return
    tracks, is_pl, pl_name = await resolve_any_music_query(ctx.guild, query, ctx.author)
    st = _MUSIC_STATE[ctx.guild.id]
    q = _MUSIC_QUEUES[ctx.guild.id]

    if is_pl and len(tracks) > 1:
        for tr in tracks:
            q.append(tr)
        if not st["now_playing"]:
            st["now_playing"] = q.popleft()
            st["started_at"] = time.time()
            _MUSIC_HISTORY[ctx.guild.id].append(st["now_playing"])
            await update_voice_channel_music_status(ctx.guild)
        desc = (
            f"{E_MUSIC} Added **`{len(tracks)}`** tracks from playlist **[{sanitize_track_title(pl_name)}]({query})**\n"
            f"{E_ARR} **Requested By:** {ctx.author.mention}"
        )
        return await send(ctx, f"{E_MUSIC} Playlist Added to Queue", desc, color=BRIGHT_GREEN)

    track = tracks[0]
    if not st["now_playing"]:
        st["now_playing"] = track
        st["started_at"] = time.time()
        st["paused"] = False
        _MUSIC_HISTORY[ctx.guild.id].append(track)
        await update_voice_channel_music_status(ctx.guild)
        return await ctx.reply(
            embed=build_faasle_nowplaying_embed(ctx, track),
            view=FaaslePlayerControllerView(ctx.guild),
            mention_author=False
        )
    else:
        q.append(track)
        desc = (
            f"{E_MUSIC} **[{track['title']}]({track['uri']})** — `{track['author']}`\n"
            f"{E_DOT} **Duration:** `{track['duration']}` • **Position in Queue:** `#{len(q)}`\n"
            f"{E_DOT} **Requested By:** {ctx.author.mention}"
        )
        return await send(ctx, f"{E_MUSIC} Added to Queue", desc, color=BRIGHT_GREEN, thumb=track.get("artwork"))

@C("nowplaying", aliases=["nowp", "np"])
async def music_np_cmd(ctx):
    st = _MUSIC_STATE[ctx.guild.id]
