@bot.event
async def on_voice_state_update(member: discord.Member, before: discord.VoiceState, after: discord.VoiceState):
    g = member.guild
    rid = cfg(g.id).get("vcrole")
    r = g.get_role(rid) if rid else None
    if r and not dangerous(r):
        if not before.channel and after.channel:
            try:
                await member.add_roles(r, reason=R("VC Role Join"))
            except Exception:
                pass
        elif before.channel and not after.channel:
            try:
                await member.remove_roles(r, reason=R("VC Role Leave"))
            except Exception:
                pass

    # Check if everyone left the music voice channel and 24/7 mode is off
    vc = g.voice_client
    if vc and vc.channel and before.channel == vc.channel:
        non_bots = [m for m in vc.channel.members if not m.bot]
        if len(non_bots) == 0:
            st = _MUSIC_STATE[g.id]
            if not st.get("247", False):
                _MUSIC_QUEUES[g.id].clear()
                st["now_playing"] = None
                try:
                    await vc.disconnect(force=True)
                except Exception:
                    pass

@bot.event
async def on_ready():
    if HAS_LAVALINK and not hasattr(bot, "lavalink"):
        try:
            bot.lavalink = lavalink.Client(bot.user.id)
            for ident, ncfg in FAASLE_MUSIC_NODES.items():
                bot.lavalink.add_node(
                    host=ncfg["host"],
                    port=ncfg["port"],
                    password=ncfg["password"],
                    region="us",
                    name=ncfg["identifier"],
                    ssl=ncfg["secure"]
                )
        except Exception:
            pass
    for g in bot.guilds:
        snapshot_guild(g)
    print(f"{BOT_NAME} ({BOT_VERSION}) is ONLINE as {bot.user} across {len(bot.guilds)} servers! Total registered commands: {len(bot.commands)}")

